const photoFoodRender=renderFoods;renderFoods=function(){photoFoodRender();if(state.view!=='explore'||contentTab!=='foods')return;for(const card of document.querySelectorAll('.foodCard')){const pic=addedFoodPhotos[card.dataset.foodName];if(!pic)continue;const cap=document.createElement('p');cap.className='photoAttribution';cap.textContent='음식 참고 사진 · 특정 식당의 제공 메뉴 아님';const link=document.createElement('a');link.href=pic.source;link.target='_blank';link.rel='noopener';link.textContent='사진 출처';cap.append(' · ',link);card.querySelector('.foodPhoto')?.after(cap)}if(typeof localize==='function')localize()};
